            text-align: left;
            color: green;
        }
    </style>
</head>
<body>
    <div id="chat-container"></div>
    <input type="text" id="user-input" placeholder="Type your message here...">
    <button onclick="sendMessage()">Send</button>

    <script src="./index.js"></script>
</body>
</html>
```

### Step 5: Implement the Chat Logic

Update your `index.js` to include the chat functionality:

```javascript
import { BlenderbotForConditionalGeneration } from '@huggingface/transformers';
import * as tf from '@tensorflow/tfjs-node';

let model;

async function main() {
    model = await BlenderbotForConditionalGeneration.fromPretrained('facebook/blenderbot-400m-distill');
    console.log('Model loaded successfully!');
}

function sendMessage() {
    const userInput = document.getElementById('user-input').value;
    if (userInput.trim()) {
        appendMessage(userInput, 'user');
        generateResponse(userInput).then(response => {
            appendMessage(response, 'bot');
        });
        document.getElementById('user-input').value = '';
    }
}

function appendMessage(message, sender) {
    const chatContainer = document.getElementById('chat-container');
    const messageElement = document.createElement('div');
    messageElement.className = `message ${sender}-message`;
    messageElement.textContent = message;
    chatContainer.appendChild(messageElement);
}

async function generateResponse(inputText) {
    try {
        const inputs = model.prepareInputs(inputText);
        const outputs = await model.generate(inputs);
        return outputs.text;
    } catch (error) {
        console.error('Error generating response:', error);
        return 'Sorry, there was an error processing your request.';
    }
}

main().catch(error => {
    console.error('Error loading model:', error);
});
```

