```ocaml
open Core

let gl = Gl.init ()

let program =
  let vertex_shader =
    "void main() { gl_Position = vec4(0.0, 0.0, 0.0, 1.0); }"
  in
  let fragment_shader =
    "void main() { gl_FragColor = vec4(1.0, 0.0, 0.0, 1.0); }"
  in
  let compute_shader =
    "
      #version 430 core
      layout (local_size_x = 1) in;
      uniform int n;
      uniform float a[n];
      uniform float b[n];
      layout (std430, binding = 0) buffer Result {
        float result;
      };
      void main() {
        result = 0.0;
        for (int i = 0; i < n; ++i) {
          result += a[i] * b[i];
        }
      }
    "
  in
  let program = Gl.create_program () in
  let vertex_shader_id = Gl.create_shader Gl.vertex_shader in
  let fragment_shader_id = Gl.create_shader Gl.fragment_shader in
  let compute_shader_id = Gl.create_shader Gl.compute_shader in
  Gl.shader_source ~source:vertex_shader vertex_shader_id;
  Gl.compile_shader vertex_shader_id;
  Gl.attach_shader program vertex_shader_id;
  Gl.shader_source ~source:fragment_shader fragment_shader_id;
  Gl.compile_shader fragment_shader_id;
  Gl.attach_shader program fragment_shader_id;
  Gl.shader_source ~source:compute_shader compute_shader_id;
  Gl.compile_shader compute_shader_id;
  Gl.attach_shader program compute_shader_id;
  Gl.link_program program;
  program
;;

let data =
  [| 1.0; 2.0; 3.0 |]
;;

let result =
  let buffer = Gl.create_buffer () in
  Gl.bind_buffer Gl.array_buffer buffer;
  Gl.buffer_data ~data:(Gl.float_array data) Gl.static_draw;
  let n = Array.length data in
  let a = Gl.uniform_location program "a" in
  let b = Gl.uniform_location program "b" in
  let result = Gl.uniform_location program "result" in
  Gl.use_program program;
  Gl.uniform_1i a n;
  Gl.uniform_1i b n;
  Gl.uniform_1f result 0.0;
  Gl.dispatch_compute 1 1 1;
  Gl.memory_barrier Gl.texture_fetch_barrier;
  let result = Gl.get_uniform_f result in
  result
;;

Printf.printf "Dot product: %f\n" result
```

