Certainly! Below is an example of how you might implement a simple raycasting algorithm in GLSL, which can be used to render a 2D or 3D environment from a first-person perspective.

### Vertex Shader

The vertex shader will pass the position of each vertex to the fragment shader. In this case, we'll use a simple identity transformation since we're dealing with a flat plane.

```glsl
#version 330 core

layout(location = 0) in vec3 aPos;

out vec3 vPosition;

void main()
{
    gl_Position = vec4(aPos, 1.0);
    vPosition = aPos;
}
```

### Fragment Shader

The fragment shader will perform the actual raycasting calculations. We'll assume that the world is represented by a grid of tiles, where each tile has a height value.

```glsl
#version 330 core

in vec3 vPosition;

uniform mat4 viewMatrix; // The camera's view matrix
uniform mat4 projectionMatrix; // The projection matrix
uniform float playerX; // Player's X position
uniform float playerY; // Player's Y position
uniform float playerAngle; // Player's facing angle
uniform int mapWidth; // Width of the map
uniform int mapHeight; // Height of the map
uniform sampler2D heightMap; // Texture containing the height values of the map

out vec4 FragColor;

const float FOV = 60.0; // Field of view in degrees
const float Z_NEAR = 0.1; // Near clipping plane
const float Z_FAR = 100.0; // Far clipping plane

vec2 getRayDirection(float x)
{
    float alpha = (x / 512.0 - 0.5) * tan(radians(FOV)) + tan(playerAngle);
    return vec2(cos(alpha), sin(alpha));
}

float getHeight(vec2 coords)
{
    return texture(heightMap, coords).r;
}

void main()
{
    vec2 screenCoords = gl_FragCoord.xy / 512.0; // Assuming a 512x512 window
    vec2 rayDir = getRayDirection(screenCoords.x);

    float depth = 0.0;
    bool hit = false;

    for (int i = 0; i < 100; ++i)
    {
        float x = playerX + rayDir.x * depth;
        float y = playerY + rayDir.y * depth;

        if (x < 0 || x >= mapWidth || y < 0 || y >= mapHeight)
        {
            break;
        }

        float h = getHeight(vec2(x / mapWidth, y / mapHeight));

        if (h > 0.0 && h < 1.0)
        {
            hit = true;
            break;
        }

        depth += 0.1;
    }

    if (!hit)
    {
        depth = 100.0; // Set a default distance if no hit was found
    }

    float wallHeight = 512.0 / (depth * tan(radians(FOV)));

    if (wallHeight > 512.0)
    {
        wallHeight = 512.0;
    }

    float color = mix(0.0, 1.0, depth / 100.0); // Simple gradient based on depth

    FragColor = vec4(color, color, color, 1.0);
}
```

### Explanation

- **Vertex Shader**: This shader simply passes the vertex positions to the fragment shader.
- **Fragment Shader**:
  - `getRayDirection`: Calculates the direction of the ray based on the current pixel's horizontal coordinate and the player's orientation.
  - `getHeight`: Retrieves the height value at a given coordinate from the height map texture.
  - The main loop iterates over possible distances along the ray, checking for intersections with the ground. If a valid intersection is found, it sets the `hit` flag and breaks out of the loop.
  - The final color is determined by a simple gradient based on the distance to the nearest object.

