```rust
use std::env;
use std::process;

fn main() {
    // Get command line arguments
    let args: Vec<String> = env::args().collect();

    if args.len() < 3 {
        eprintln!("Usage: {} <pattern> <text>", args[0]);
        process::exit(1);
    }

    let pattern = &args[1];
    let text = &args[2];

