Here is a simple example of a Metal compute kernel for Gaussian blurring an image:

```metal
#include <metal_stdlib>
using namespace metal;

kernel void gaussian_blur(
    texture2d<float, access::read> input [[texture(0)]],
    texture2d<float, access::write> output [[texture(1)]],
    uint2 gid [[thread_position_in_grid]]
) {
    // Define the kernel size and standard deviation
    const int kernelSize = 5;
    const float sigma = 1.0f;

    // Calculate the weights for the Gaussian distribution
    float sumWeights = 0.0f;
    float weights[kernelSize];
    for (int i = 0; i < kernelSize; ++i) {
        float x = i - (kernelSize / 2);
        weights[i] = exp(-x * x / (2 * sigma * sigma));
        sumWeights += weights[i];
    }

    // Normalize the weights
    for (int i = 0; i < kernelSize; ++i) {
        weights[i] /= sumWeights;
    }

    // Apply the Gaussian blur
    float4 result = float4(0.0f);
    for (int i = 0; i < kernelSize; ++i) {
        for (int j = 0; j < kernelSize; ++j) {
            int x = gid.x + i - (kernelSize / 2);
            int y = gid.y + j - (kernelSize / 2);
            if (x >= 0 && x < input.width() && y >= 0 && y < input.height()) {
                result += input.read(x, y) * weights[i] * weights[j];
            }
        }
    }

    // Write the result to the output texture
    output.write(result, gid);
}
```

