```javascript
function findEntityInJson(jsonData, entityKey) {
    // Helper function to perform recursive search
    function search(obj, path = []) {
        if (typeof obj === 'object' && obj !== null) {
            for (let [key, value] of Object.entries(obj)) {
                const newPath = [...path, key];
                if (key === entityKey) {
                    results.push({ value: value, path: newPath });
                }
                if (typeof value === 'object') {
                    search(value, newPath);
                }
            }
        }
    }

    let results = [];
    search(JSON.parse(jsonData));
    return results;
}

// Example usage:
const jsonData = `{
    "name": "John",
    "age": 30,
    "address": {
        "street": "123 Main St",
        "city": "Anytown",
        "state": "Anystate"
