```python
import numpy as np

# Define the size of the board
ROWS = 6
COLUMNS = 7

# Initialize the board
board = np.zeros((ROWS, COLUMNS))

def print_board(board):
    # Print the current state of the board
    for row in range(ROWS):
        print("|", end="")
        for col in range(COLUMNS):
            if board[row][col] == 0:
                print("   |", end="")
            elif board[row][col] == 1:
                print(" X |", end="")
            else:
                print(" O |", end="")
        print()

def is_valid_location(board, col):
    # Check if the selected column is valid (not full)
    return board[ROWS - 1][col] == 0

def get_next_open_row(board, col):
    # Get the next available row in the selected column
    for r in range(ROWS):
        if board[r][col] == 0:
            return r

def drop_piece(board, row, col, piece):
    # Drop the player's piece into the selected row and column
    board[row][col] = piece

def winning_move(board, piece):
    # Check for a winning move horizontally, vertically, or diagonally
    # Horizontal check
    for c in range(COLUMNS - 3):
        for r in range(ROWS):
            if board[r][c] == piece and board[r][c + 1] == piece and board[r][c + 2] == piece and board[r][c + 3] == piece:
                return True

    # Vertical check
    for c in range(COLUMNS):
        for r in range(ROWS - 3):
            if board[r][c] == piece and board[r + 1][c] == piece and board[r + 2][c] == piece and board[r + 3][c] == piece:
                return True

    # Positive diagonal check
    for c in range(COLUMNS - 3):
        for r in range(ROWS - 3):
            if board[r][c] == piece and board[r + 1][c + 1] == piece and board[r + 2][c + 2] == piece and board[r + 3][c + 3] == piece:
                return True

    # Negative diagonal check
    for c in range(COLUMNS - 3):
        for r in range(3, ROWS):
            if board[r][c] == piece and board[r - 1][c + 1] == piece and board[r - 2][c + 2] == piece and board[r - 3][c + 3] == piece:
                return True

    return False

def main():
    turn = 0
    game_over = False

    while not game_over:
        # Player 1's turn
        if turn % 2 == 0:
            col = int(input("Player 1, make your selection (0-6): "))
            if is_valid_location(board, col):
                row = get_next_open_row(board, col)
                drop_piece(board, row, col, 1)
                if winning_move(board, 1):
                    print_board(board)
                    print("Player 1 wins!")
                    game_over = True
        else:
            # Player 2's turn
            col = int(input("Player 2, make your selection (0-6): "))
            if is_valid_location(board, col):
                row = get_next_open_row(board, col)
                drop_piece(board, row, col, 2)
                if winning_move(board, 2):
                    print_board(board)
                    print("Player 2 wins!")
                    game_over = True

        print_board(board)
        turn += 1

if __name__ == "__main__":
    main()
```

This code defines a basic Connect-4 game where two players take turns dropping their pieces into columns on a 6x7 grid. The game checks for a win after each move by checking for four consecutive pieces in any direction.

